#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

bool saveLines(const std::filesystem::path& file, const std::vector<std::string>& lines)
{
    std::ofstream out{ file };
    if (!out)
    {
        return false;
    }
    for (const std::string& line : lines)
    {
        out << line << '\n';
    }
    return true;
}

std::vector<std::string> loadLines(const std::filesystem::path& file)
{
    std::vector<std::string> lines{};
    std::ifstream in{ file };
    std::string line{};
    while (std::getline(in, line))
    {
        lines.push_back(line);
    }
    return lines;
}

