namespace fs = std::filesystem;
struct TempFile { fs::path path{ "xenon_lines_test.txt" }; TempFile() { fs::remove(path); } ~TempFile() { std::error_code ec; fs::remove(path, ec); } };
using Lines = std::vector<std::string>;

TEST("what is saved can be loaded") { TempFile t; CHECK(saveLines(t.path, { "first", "second line", "", "fourth" })); CHECK_EQ(loadLines(t.path), (Lines{ "first", "second line", "", "fourth" })); }
TEST("saving again replaces the old contents") { TempFile t; saveLines(t.path, { "a", "b", "c" }); saveLines(t.path, { "z" }); CHECK_EQ(loadLines(t.path), (Lines{ "z" })); }
TEST("a missing file loads as nothing") { TempFile t; CHECK(loadLines(t.path).empty()); CHECK(loadLines("no/such/folder/file.txt").empty()); }
TEST("an unwritable path reports failure") { CHECK(!saveLines("no/such/folder/file.txt", { "x" })); }

